	(164, '_site_transient_wp_plugin_dependencies_plugin_data', 'a:1:{s:9:"elementor";a:35:{s:4:"name";s:63:"Elementor Website Builder &#8211; more than just a page builder";s:4:"slug";s:9:"elementor";s:7:"version";s:5:"4.1.1";s:6:"author";s:64:"<a href="https://profiles.wordpress.org/elemntor/">Elementor</a>";s:14:"author_profile";s:40:"https://profiles.wordpress.org/elemntor/";s:12:"contributors";a:1:{s:8:"elemntor";a:3:{s:7:"profile";s:40:"https://profiles.wordpress.org/elemntor/";s:6:"avatar";s:120:"https://secure.gravatar.com/avatar/7d70f15d78757f876d1847a8f87dd93e1d9c168264b4aeeaf72058656690d05b?s=96&d=monsterid&r=g";s:12:"display_name";s:9:"Elementor";}}s:8:"requires";s:3:"6.6";s:6:"tested";s:3:"7.0";s:12:"requires_php";s:3:"7.4";s:16:"requires_plugins";a:0:{}s:6:"rating";i:90;s:7:"ratings";a:5:{i:5;i:6129;i:4;i:233;i:3;i:120;i:2;i:113;i:1;i:663;}s:11:"num_ratings";i:7258;s:11:"support_url";s:47:"https://wordpress.org/support/plugin/elementor/";s:15:"support_threads";i:58;s:24:"support_threads_resolved";i:48;s:15:"active_installs";i:10000000;s:12:"last_updated";s:22:"2026-05-27 11:27am GMT";s:5:"added";s:10:"2016-05-30";s:8:"homepage";s:87:"https://elementor.com/?utm_source=wp-plugins&utm_campaign=plugin-uri&utm_medium=wp-dash";s:8:"sections";a:6:{s:11:"description";s:25808:"<p><span class="embed-youtube" style="text-align:center; display: block;"><iframe loading="lazy" class="youtube-player" width="750" height="422" src="https://www.youtube.com/embed/ROEC0CPRO3w?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=fr-FR&#038;autohide=2&#038;wmode=transparent" allowfullscreen="true" style="border:0;" sandbox="allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox"></iframe></span></p>\n<h4>THE #1 NO CODE DRAG &amp; DROP WORDPRESS WEBSITE BUILDER POWERING 22M+ WEBSITES WORLDWIDE, NOW WITH AI.</h4>\n<p>Elementor, the leading WordPress website creation platform, empowers you to build professional, pixel-perfect websites seamlessly with its no-code, drag-and-drop Atomic Editor.</p>\n<p>Supporting the full website lifecycle, Elementor enables you to confidently build, optimize, and manage your website with extended capabilities such as AI-powered creation, image optimization, transactional email delivery, accessibility tools, performance boosters, and more.</p>\n<p>Now in version 4 &#8211; the Atomic Editor! Introducing a new generation of performance-first atomic building blocks that allow you to control every atomic part with no limits or locked layouts. Define your global design systems and reusable components once, and they apply everywhere instantly &#8211; turning hours or even days of work into single clicks.</p>\n<p>Unlock all features with <strong><a href="https://go.elementor.com/wp-repo-description-tab-elementor-pro-pro-features/" rel="nofollow ugc">Elementor One</a></strong>.</p>\n<p>Need fast and secure cloud hosting for your Elementor site? Try out <strong><a href="https://elemn.to/repo-hosting" rel="nofollow ugc">Elementor Host</a></strong> Powered by Google Cloud &amp; Cloudflare. 4.9/5 TrustPilot score.</p>\n<h3>🌟 Créez des sites professionnels époustouflants</h3>\n<ul>\n<li><strong><a href="https://go.elementor.com/feature-page-editor/" rel="nofollow ugc">Intuitive Drag &amp; Drop Builder</a></strong>: Build any website with our no-code, drag-and-drop Editor. Achieve design precision with full control over layout and style.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-feature-page/" rel="nofollow ugc">Pixel-Perfect Design Tools</a></strong>: Upload SVGs, apply masks, gradients, box shadows, headline effects, shape dividers, and use built-in CSS controls for advanced customization.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-library-full-website-kit/" rel="nofollow ugc">Template Library</a></strong>: Apply complete website kits for instant setups, or choose from a vast library of single pages, blocks, and pop-up templates.</li>\n<li><strong><a href="https://go.elementor.com/feature-page-editor/" rel="nofollow ugc">Advanced Widgets</a></strong>: Access over 40 FREE widgets, including heading, image, text editor, video, button, gallery, carousels, and more.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-elementor-ai/" rel="nofollow ugc">AI Capabilities</a></strong>: Revolutionize your design and content creation process with native AI integration. Instantly create sections, text, code, and images.</li>\n</ul>\n<h4>🗝️ Fonctionnalités clés :</h4>\n<ul>\n<li><strong><a href="https://go.elementor.com/feature-page-global-settings/" rel="nofollow ugc">Design System</a></strong>: Use Variables and Classes for consistent colors, typography, and design elements, ensuring a cohesive, professional look that updates everywhere globally.</li>\n<li><strong><a href="https://go.elementor.com/feature-page-responsive-design/" rel="nofollow ugc">Responsive Design</a></strong>: Optimize your design for every device with custom breakpoints, ensuring a seamless desktop, tablet, and mobile experience.</li>\n<li><strong>Mask Shapes</strong>: Turning any element, like an image or video, into whatever shape you desire to create standout designs.</li>\n<li><strong>CSS Transform</strong>: Use CSS Transform to rotate, scale, and skew elements, adding dynamic styling to your site.</li>\n<li><strong>Entrance Animations</strong>: Add entrance animations to elements to create engaging and interactive user experiences.</li>\n<li><strong><a href="https://elementor.com/features/#SaveBackup" rel="nofollow ugc">Revision History</a></strong>: Elementor’s Revision History feature enables users to track and revert to previous versions of their designs, providing peace of mind and flexibility during the creative process.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-developers-developers-website/" rel="nofollow ugc">Developer-Friendly</a></strong>: Equipped with extensive documentation, API, developer tools, and custom code areas, Elementor offers a conducive environment for developers to extend its capabilities and create custom solutions.</li>\n<li><strong><a href="https://elementor.com/features/contact-button/" rel="nofollow ugc">Floating Buttons</a></strong>: Enhance user interaction with customizable, floating action buttons that stay in view as users scroll.</li>\n<li><strong>Components [Pro]</strong>: Reuse the same building blocks across pages and sites, and update them everywhere they appear. Including controlled content editing, allowing collaborators and clients to update only exposed content properties without breaking layout or styling.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-industry-leading-theme-builder/" rel="nofollow ugc">Theme Builder</a> [Pro]</strong>: Design every part of your site—headers, footers, posts, and archives—for complete control over appearance.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-popup-builder/" rel="nofollow ugc">Popup Builder</a> [Pro]</strong>: Create eye-catching popups with Elementor’s Popup Builder, equipped with advanced targeting and triggering options to optimize user engagement and conversions.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-professional-form-builder-and-submission-log/" rel="nofollow ugc">Forms</a> [Pro]</strong>: Design and integrate custom forms, utilizing advanced features and integrations to capture and manage submissions effectively.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-woocommerce-builder/" rel="nofollow ugc">WooCommerce Builder</a> [Pro]</strong>:  Integrate Elementor with WooCommerce to design custom product pages, shop layouts, archives, carts, checkout pages, my account, and more, enhancing your store’s visual appeal and functionality.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-dynamic-content/" rel="nofollow ugc">Dynamic Content</a> [Pro]</strong>: Leverage dynamic content capabilities to create personalized and interactive web experiences by connecting your designs to various data sources.</li>\n<li><strong><a href="https://go.elementor.com/features-page-notes/" rel="nofollow ugc">Notes</a> [Pro]</strong>: Enhance team collaboration by using Elementor’s Notes feature to leave feedback and comments directly on the design interface.</li>\n<li><strong>Custom Code [Pro]</strong>: Insert custom code to extend the functionality of your site, offering flexibility for advanced customizations.</li>\n<li><strong>Custom CSS [Pro]</strong>: Apply Custom CSS to fine-tune the styling of elements, ensuring precise control over the design aspects.</li>\n<li><strong><a href="https://go.elementor.com/wp-repo-description-tab-pro-features-motion-effects/" rel="nofollow ugc">Motion Effects</a> [Pro]</strong>: Add advanced motion effects to elements for a more dynamic and engaging user experience.</li>\n<li><strong>Custom Fonts &amp; Icons [Pro]</strong>: Upload and use custom fonts and icons to match your brand’s identity.</li>\n</ul>\n<h4>😍 Elementor FREE widgets</h4>\n<p>Unlock the potential of Elementor with our comprehensive suite of free widgets and tools, designed to empower your website creation process and elevate your design capabilities:</p>\n<ul>\n<li><strong>Titre</strong>. Ajouter un titre attirant.</li>\n<li><strong>Image</strong>. Contrôlez la taille, l’opacité et bien plus encore.</li>\n<li><strong>Text Editor</strong>. Just like the WordPress text editor.</li>\n<li><strong>Video</strong>. Add YouTube, Vimeo, VideoPress, Dailymotion or self-hosted videos.</li>\n<li><strong>Button</strong>. Create interactive buttons.</li>\n<li><strong>Link in Bio</strong>. Build link in bio components to promote your business / services.</li>\n<li><strong>Boîte d’image</strong>. Une boîte qui contient une image, un titre et un texte.</li>\n<li><strong>Témoignages</strong>. Témoignages de clients/clientes.</li>\n<li><strong>Icône</strong>. Placez une ou plusieurs des 600+ icônes disponibles.</li>\n<li><strong>Boîte à icônes</strong>. Une icône, un titre et un texte dans un seul widget.</li>\n<li><strong>Social Icons</strong>. Link to your social pages with the Facebook/X (formerly Twitter) icons.</li>\n<li><strong>Galerie d’images</strong>. Affiche vos images dans une grille.</li>\n<li><strong>Carrousel d’images</strong>. Un carrousel rotatif ou un diaporama des images choisies.</li>\n<li><strong>Liste d’icônes</strong>. Utilisez n’importe quelle icône pour créer une liste à puces.</li>\n<li><strong>Compteur</strong>. Afficher des statistiques et des chiffres de façon croissante.</li>\n<li><strong>Barre de progression</strong>. Inclure une barre de progression progressive.</li>\n<li><strong>Nested Tabs</strong>. Display content in vertical or horizontal tabs.</li>\n<li><strong>Nested Accordion</strong>. Display any type of content in collapsible sections.</li>\n<li><strong>Rating</strong>. Display how many stars (or another icon) other visitors gave.</li>\n<li><strong>Alerte</strong>. Ajoutez une boîte d’alerte colorée pour attirer l’attention de vos visiteurs.</li>\n<li><strong>HTML</strong>. Insérez du code dans la page. </li>\n<li><strong>Code court</strong>. Insérez des codes courts depuis n’importe quelle extension dans la page.</li>\n<li><strong>Ancre de menu</strong>. Lier n’importe quel menu à cette ancre.</li>\n<li><strong>Lire plus</strong>. Définissez la coupure « Lire plus »> pour l’extrait dans les pages d’archive.</li>\n<li><strong>Colonne latérale</strong>. Ajouter des colonnes latérales dans la page.</li>\n<li><strong>Google Maps</strong>. Intégrer des cartes dans la page.</li>\n<li><strong>SoundCloud</strong>. Add SoundCloud audio bits.</li>\n<li><strong>Séparateur</strong>. Séparez le contenu grâce à un séparateur conçu à cet effet.</li>\n<li><strong>Espaceur</strong>. Ajoutez de l’espace entre les éléments.</li>\n<li><strong>Chemin de texte</strong>. Attachez votre texte à un chemin.</li>\n<li><strong>Et comptant&#8230;</strong></li>\n</ul>\n<h3>🚀 Améliorez votre site</h3>\n<p><strong><a href="https://go.elementor.com/wp-repo-description-tab-performance-performance-page/" rel="nofollow ugc">Sites hautes performances</a></strong> : les performances de votre site ont une influence sur l’expérience des visiteurs et visiteuse, puis sur le classement dans les résultats de recherche. Elementor, en partenariat avec Google Chrome, améliore les performances en permanence sans jamais compromettre la mise en page de votre site.</p>\n<p><strong>Les fonctionnalités clés comprennent :</strong></p>\n<ul>\n<li><strong>Reduced DOM Output</strong>: Streamlined HTML structure for faster rendering.</li>\n<li><strong>Improved Media File Loading</strong>: Optimized loading of images, videos, and other media assets.</li>\n<li><strong>Reduced CSS and JS Files</strong>: Minimized stylesheets and scripts individually loaded only on demand for quicker loading times.</li>\n<li><strong>Lazy Loading</strong>: Deferred loading of non-critical resources to improve initial page load speed.</li>\n<li><strong>Faster Font Loading</strong>: Efficient delivery of web fonts to enhance text rendering speed.</li>\n<li><strong>Optimized Front-End Asset Loading</strong>: Efficient loading of assets like JavaScript and CSS to minimize render-blocking.</li>\n<li><strong>Element Caching</strong>: Cache frequently accessed design elements to reduce server response time and enhance overall performance.</li>\n</ul>\n<h3>🔥 Elementor Editor Pro Features</h3>\n<p>Create unparalleled websites while saving time, money and resources with <a href="https://go.elementor.com/wp-repo-description-tab-elementor-pro-elementor-pro/" rel="nofollow ugc">Elementor Editor Pro</a>’s full website builder. Get access to 100+ professional widgets, features, and tools.</p>\n<p><strong>Editor Pro Design Widgets:</strong></p>\n<ol>\n<li><strong>Posts</strong>: Display your blog posts with customizable layouts and styles.</li>\n<li><strong>Share Buttons</strong>: Allow visitors to easily share your content on various social media platforms.</li>\n<li><strong>Portfolio</strong>: Showcase your work or projects with stunning portfolio layouts.</li>\n<li><strong>Slides</strong>: Create dynamic slideshows with custom animations and transitions.</li>\n<li><strong>Form</strong>: Design and customize advanced forms for user interaction and data collection.</li>\n<li><strong>Login</strong>: Add a login form or user registration module to your website.</li>\n<li><strong>Nav Menu</strong>: Customize and style your website&rsquo;s navigation menu for better user experience.</li>\n<li><strong>Animated Headline</strong>: Create attention-grabbing headlines with animated effects.</li>\n<li><strong>Price Table</strong>: Display pricing plans or packages in a structured and visually appealing format.</li>\n<li><strong>Price List</strong>: Showcase a list of prices or services with customizable styling options.</li>\n<li><strong>Gallery</strong>: Create beautiful image galleries with various layout options and lightbox support.</li>\n<li><strong>Flip Box</strong>: Add interactive flip animations to highlight content or features.</li>\n<li><strong>CTA</strong> : Poussez vos utilisateurs et utilisatrices à interagir et augmentez les conversions grâce à des sections d’appel à l’action convaincantes.</li>\n<li><strong>Carrousel de médias</strong> : Affichez un carrousel de fichiers médias tels que des images ou des vidéos.</li>\n<li><strong>Testimonial Carousel</strong>: Display client testimonials in a carousel format for social proof.</li>\n<li><strong>Nested Carousel</strong>: Create nested carousels for more complex content organization.</li>\n<li><strong>Loop Carousel</strong>: Display content in a looped carousel for continuous viewing.</li>\n<li><strong>Table Of Content</strong>: Generate a table of contents for longer articles or guides to improve navigation.</li>\n<li><strong>Countdown</strong>: Add countdown timers to create urgency for promotions or events.</li>\n<li><strong>Facebook Page</strong>: Embed your Facebook page feed or content onto your website.</li>\n<li><strong>Blockquote</strong>: Highlight quotes or testimonials with stylish formatting options.</li>\n<li><strong>Template</strong>: Save and reuse design templates for consistent branding and layout.</li>\n<li><strong>Reviews</strong>: Showcase customer reviews and ratings to build trust and credibility.</li>\n<li><strong>Facebook Button</strong>: Add buttons to promote interactions with your Facebook page or content.</li>\n<li><strong>Facebook Embed</strong>: Embed Facebook posts or content onto your website.</li>\n<li><strong>Facebook Comments</strong>: Enable Facebook comments on your website&rsquo;s pages or posts.</li>\n<li><strong>PayPal Button</strong>: Integrate PayPal buttons for easy online payments.</li>\n<li><strong>Stripe Button</strong>: Integrate Stripe payment buttons to facilitate secure online transactions.</li>\n<li><strong>Lottie Widget</strong>: Add Lottie animations to enhance visual appeal and engagement.</li>\n<li><strong>Code Highlight</strong>: Display code snippets with syntax highlighting for better readability.</li>\n<li><strong>Video Playlist</strong>: Create and customize playlists for video content on your website.</li>\n<li><strong>Mega Menu</strong>: Customize advanced menus for better navigation and displaying complex content.</li>\n<li><strong>Off Canvas</strong>: Create off-canvas areas that slide in to show extra info or menus without cluttering the main layout.</li>\n</ol>\n<p><strong>Editor Pro Theme Widgets:</strong></p>\n<p>Build and customize all the key parts of your website including headers, footers, 404 page, global archives, and more&#8230;</p>\n<ol>\n<li><strong>Post Title</strong>: Customize the title of individual blog posts or pages.</li>\n<li><strong>Post Excerpt</strong>: Display a brief summary or teaser of your blog posts.</li>\n<li><strong>Post Content</strong>: Customize the main content area of your blog posts or pages.</li>\n<li><strong>Featured Image</strong>: Set and customize featured images for blog posts or pages.</li>\n<li><strong>Author Box</strong>: Display author information and bios on blog posts.</li>\n<li><strong>Post Comments</strong>: Customize the appearance and functionality of comments sections on your website.</li>\n<li><strong>Post Navigation</strong>: Add navigation links to adjacent posts for easy browsing.</li>\n<li><strong>Post Info</strong>: Display additional information about blog posts, such as author and date.</li>\n<li><strong>Site Logo</strong>: Upload and customize your website&rsquo;s logo for branding purposes.</li>\n<li><strong>Site Title</strong>: Customize the title of your website.</li>\n<li><strong>Page Title</strong>: Customize the title of individual pages.</li>\n<li><strong>Search Bar</strong>: Add a search bar to allow users to search your website&rsquo;s content.</li>\n<li><strong>Breadcrumbs</strong>: Display hierarchical navigation paths for better user navigation.</li>\n<li><strong>Sitemap</strong>: Generate a sitemap for better search engine indexing and user navigation.</li>\n<li><strong>Loop Grid</strong>: Design and customize grid layouts for blog post archives or product listings.</li>\n</ol>\n<p><strong>Editor Pro WooCommerce Widgets:</strong></p>\n<p>Design and customize a complete online shopping experience across your entire website.</p>\n<ol>\n<li><strong>Produit</strong> : affichez des produits individuels avec des mises en page et des styles personnalisables.</li>\n<li><strong>Breadcrumbs</strong>: Display hierarchical navigation paths for better user navigation within your store.</li>\n<li><strong>Titre du produit</strong> : personnalisez le titre des produits individuels.</li>\n<li><strong>Images du produit</strong> : ajoutez et personnalisez les images pour les listes de produits.</li>\n<li><strong>Prix des produits</strong> : affichez le prix des produits individuels.</li>\n<li><strong>Ajouter au panier</strong> : ajoutez des boutons « Ajouter au panier » personnalisés pour faciliter l’achat.</li>\n<li><strong>Évaluation du produit</strong> : affichez les notes et les avis concernant les produits.</li>\n<li><strong>Stock des produits</strong> : affichez les quantités en stock des produits.</li>\n<li><strong>Métadonnées du produit</strong> : affichez des informations supplémentaires sur les produits telles que les UGS et les catégories.</li>\n<li><strong>Product Content</strong>: Customize the main content area of product descriptions.</li>\n<li><strong>Description courte</strong> : affichez de brefs résumés ou des aperçus de produits.</li>\n<li><strong>Product Data Tabs</strong>: Organize product information into tabbed sections for better organization.</li>\n<li><strong>Informations supplémentaires</strong> : affichez des détails supplémentaires sur vos produits tels que les dimensions et le poids.</li>\n<li><strong>Produits similaires</strong> : affichez des produits similaires pour encourager les achats supplémentaires.</li>\n<li><strong>Upsells</strong>: Promote upsell products to increase average order value.</li>\n<li><strong>Produits</strong> : affichez une grille ou une liste de produits avec des réglages personnalisables.</li>\n<li><strong>Ajouter au panier personnalisé</strong> : personnalisez le bouton « Ajouter au panier » pour certains produits.</li>\n<li><strong>Pages WooCommerce</strong> : créez et personnalisez des pages WooCommerce telles que les pages panier et validation de commande.</li>\n<li><strong>Product Categories</strong>: Display product categories for easy navigation within your store.</li>\n<li><strong>Panier de menu</strong> : affichez une icône de panier dans votre menu de navigation pour faciliter l’accès au panier.</li>\n<li><strong>Panier</strong> : personnalisez l’apparence et les fonctionnalités de la page panier.</li>\n<li><strong>Validation de commande</strong> : personnalisez l’apparence et les fonctionnalités de la page de validation de commande.</li>\n<li><strong>Mon compte</strong> : personnalisez l’apparence et les fonctionnalités de la zone du compte client/cliente.</li>\n<li><strong>Résumé d’achat</strong> : affichez un résumé des achats durant le processus de validation de la commande.</li>\n<li><strong>Notifications WooCommerce</strong> : personnalisez l’apparence et les fonctionnalités des notifications WooCommerce, telles que les messages de confirmation de commande.</li>\n</ol>\n<p>Build professional websites with <strong><a href="https://go.elementor.com/wp-repo-description-tab-elementor-pro-elementor-pro/" rel="nofollow ugc">Elementor Editor Pro</a></strong>!</p>\n<h4>🔒 SECURITY AND COMPLIANCE</h4>\n<p>Elementor places a paramount focus on security, evident through our acquisition of industry certifications such as ISO/IEC 27001, ISO/IEC 27017, ISO/IEC 27018, ISO/IEC 27701, and SOC 2 Type II. These certifications underscore our commitment to implementing robust security measures, and highlight our dedication to adhering to recognized industry standards.</p>\n<p>We encourage ethical security research through our <a href="https://go.elementor.com/wp-repo-description-tab-bug-crowd-bug-bounty-program/" rel="nofollow ugc">Bug Bounty program</a>. We collaborate with leading bug bounty services to provide opportunities for researchers to report vulnerabilities in our services. Our bounty programs include a triage team available 24/7/365.</p>\n<p>For more information: <a href="https://go.elementor.com/trust-center/" rel="nofollow ugc">Trust Center</a>.</p>\n<h4>♿ Meilleures pratiques en matière d’accessibilité</h4>\n<p>Elementor offers accessibility tools and enhancements to help you provide a better experience for all users. Including HTML 5 semantic, full keyboard navigation menu, ongoing improvement of features, widget, and more.</p>\n<h4>🌐 Traduit en plus de 63 langues, y compris la prise en charge RTL</h4>\n<p>Elementor supports multiple languages, typographies, and RTL, with editor translations in <a href="https://go.elementor.com/wp-repo-description-tab-wordpress-plugin-translate/" rel="nofollow ugc">over 63 languages</a>.</p>\n<p>It’s also compatible with WPML, Polylang, TranslatePress, Weglot, and more. To contribute, add a new language via <a href="https://translate.wordpress.org" rel="nofollow ugc">translate.wordpress.org</a>. See our guide on <a href="https://go.elementor.com/wp-repo-description-tab-help-center-translate/" rel="nofollow ugc">how to translate and localize the plugin</a>.</p>\n<h4>⏩ Utilisation de services tiers</h4>\n<p>To improve the user experience, Elementor may use the following 3rd party services if the required feature is enabled:</p>\n<ul>\n<li>Google Fonts – are loaded to add additional fonts to your website. Google’s <a href="https://policies.google.com/terms" rel="nofollow ugc">TOS</a> and <a href="https://policies.google.com/privacy" rel="nofollow ugc">Privacy Policy</a> apply.</li>\n<li>Some Elementor features require loading assets from Elementor.com. These assets are not used for tracking unless explicitly mentioned, requiring your approval and manual opt-in. Learn more in our <a href="https://go.elementor.com/wp-repo-description-tab-elementor-plugin-terms/" rel="nofollow ugc">TOS</a> and <a href="https://go.elementor.com/wp-repo-description-tab-elementor-plugin-privacy/" rel="nofollow ugc">Privacy Policy</a>.</li>\n</ul>\n<h4>📧 Related Products by Elementor</h4>\n<p><strong><a href="https://go.elementor.com/wp-repo-description-tab-elementor-io/" rel="nofollow ugc">Image Optimizer</a></strong>: Superior image compression for faster, high-quality website performance.</p>\n<p><strong><a href="https://go.elementor.com/wp-repo-description-tab-elementor-sm/" rel="nofollow ugc">Site Mailer</a></strong>: Reliable email management without SMTP plugins, keeping your communications streamlined and efficient.</p>\n<p><strong><a href="http://go.elementor.com/editor-acc-wp-repo" rel="nofollow ugc">Ally</a></strong>: Enhances website usability for individuals with disabilities. Ally is designed to help web creators make their websites more inclusive. It scans, detects, and remediate key accessibility violations, working seamlessly on all WordPress and Elementor websites.</p>\n<h4>📣 See What Our Users Have to Say</h4>\n<blockquote>\n<p>“Elementor is hands down the best page builder out there” – ★★★★★ <em><a href="https://wordpress.org/support/topic/elementor-is-hands-down-the-best-page-builder-out-there/" rel="ugc">Graphicvision1</a></em></p>\n<p>“An incredibly user-friendly plugin” – ★★★★★ <em><a href="https://wordpress.org/support/topic/a-wonderful-experience/" rel="ugc">Hyeyoga</a></em></p>\n<p>“Easily, my most used WP plugin” –  &hellip;</p>\n</blockquote>\n";s:12:"installation";s:1747:"<h4>Exigences minimales</h4>\n<ul>\n<li>WordPress 6.5 or greater</li>\n<li>PHP version 7.4 ou supérieure</li>\n<li>MySQL version 5.0 ou supérieure</li>\n</ul>\n<h4>Prérequis recommandés</h4>\n<ul>\n<li>PHP version 8.1 or greater</li>\n<li>MySQL version 5.6 ou supérieure</li>\n<li>Limite de mémoire WordPress de 64 Mo ou plus (128 Mo ou plus recommandé) </li>\n</ul>\n<p><span class="embed-youtube" style="text-align:center; display: block;"><iframe loading="lazy" class="youtube-player" width="750" height="422" src="https://www.youtube.com/embed/9EZ159ryFNs?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=fr-FR&#038;autohide=2&#038;wmode=transparent" allowfullscreen="true" style="border:0;" sandbox="allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox"></iframe></span></p>\n<h4>Installation</h4>\n<ol>\n<li>Installez à l&rsquo;aide de l’installateur d’extension intégré WordPress, ou décompressez le fichier zip et déposez le contenu dans le répertoire <code>wp-content/plugins/</code> de votre installation WordPress.</li>\n<li>Activez l’extension dans le menu « Extensions » de WordPress.</li>\n<li>Allez à Pages &gt; Ajouter une nouvelle</li>\n<li>Appuyez sur le bouton &lsquo;Modifier avec Elementor&rsquo;.</li>\n<li>Vous pouvez maintenant glisser et déposer des widgets du panneau de gauche sur la zone de contenu, aussi bien que d&rsquo;ajouter de nouvelles sections et colonnes qui composent la structure de la page.</li>\n</ol>\n<p>Pour de la documentation et des tutoriels, visitez notre <a href="https://docs.elementor.com/?utm_source=wp-repo&amp;utm_medium=link&amp;utm_campaign=readme" rel="nofollow ugc">base de connaissance</a>.</p>\n";s:3:"faq";s:5137:"\n<dt id="how%20do%20i%20install%20elementor%20editor%3F">\nHow do I install Elementor Editor?\n</h4>\n<p>\n<p>To install the free version of Elementor Editor, follow the steps below:<br />\nFrom your WordPress dashboard -&gt; Go to Plugins -&gt; Click on &lsquo;Add new&rsquo;-&gt; In the Search field, enter Elementor and choose Elementor website builder.<br />\nPress install -&gt; After installation, click Activate.</p>\n</p>\n<dt id="does%20elementor%20editor%20work%20with%20all%20the%20themes%3F">\nDoes Elementor Editor work with all the themes?\n</h4>\n<p>\n<p>Elementor Editor works all the themes that respect the coding standards of WordPress set by its Codex. It is recommended to use Elementor&rsquo;s <a href="https://go.elementor.com/wp-repo-description-tab-hello-theme-hello-theme/" rel="nofollow ugc">Hello Theme</a>, a lightweight blank canvas, to enjoy full flexibility when using Elementor Editor, and optimize your experience.</p>\n</p>\n<dt id="is%20elementor%20editor%20compatible%20with%20gutenberg%3F">\nIs Elementor Editor compatible with Gutenberg?\n</h4>\n<p>\n<p>Elementor Editor and Gutenberg work seamlessly together. As a user, you can easily decide which editor to use at every point while editing your site.</p>\n</p>\n<dt id="can%20i%20create%20an%20online%20store%3F">\nPuis-je créer une boutique en ligne ? \n</h4>\n<p>\n<p>Yes, with the Elementor Editor Pro WooCommerce Builder you can customize every page of your store to create an amazing customer experience that drives sales.</p>\n</p>\n<dt id="does%20it%20work%20with%20other%20wordpress%20plugins%3F">\nFonctionne-t-il avec d’autres extensions WordPress ?\n</h4>\n<p>\n<p>It works with almost all the plugins. If you experience an incompatibility issue, please report it to us and to the plugin that conflicts with Elementor Editor.</p>\n</p>\n<dt id="do%20i%20need%20to%20know%20how%20to%20code%3F">\nDois-je savoir comment coder ?\n</h4>\n<p>\n<p>No! Elementor Editor provides you with all the widgets and features that you need to build a professional website without using code.</p>\n</p>\n<dt id="do%20i%20need%20to%20know%20how%20to%20design%3F">\nDois-je savoir comment concevoir ?\n</h4>\n<p>\n<p>No, you can choose between professionally designed kits and templates that fit to every industry and have all you need to create your own professional website.</p>\n</p>\n<dt id="will%20elementor%20editor%20slow%20down%20my%20website%3F">\nWill Elementor Editor slow down my website?\n</h4>\n<p>\n<p>As Elementor prioritizes speed and performance, you enjoy better and faster performance with each new version of the Editor. When testing the same page layout on older versions you can see a significant performance improvement, from a score of 82 in Google PageSpeed Insight in version 3.1, to a score of 95 i in version 3.5.</p>\n</p>\n<dt id="is%20my%20site%20secure%20with%20elementor%20editor%3F">\nIs my site secure with Elementor Editor?\n</h4>\n<p>\n<p>The security of your website is extremely important to us and we take proactive measures to assure that your websites are secure. Elementor is ISO 27001 certified, and has a dedicated team of security professionals that implements industry best-practices for maximum security and compliance, 24/7.</p>\n<p>There is also a managed security Bug Bounty program, utilizing the community power by enabling 24/7/365 crowdsourced vulnerability detection.</p>\n</p>\n<dt id="can%20i%20buy%20templates%20separately%3F">\nPuis-je acheter les modèles séparément ? \n</h4>\n<p>\n<p>Of course, you can use any template that supports Elementor Editor.</p>\n</p>\n<dt id="is%20elementor%20editor%20compatible%20with%20post%20and%20custom%20post%20types%3F">\nIs Elementor Editor compatible with Post and Custom Post Types?\n</h4>\n<p>\n<p>Bien sûr ! Vous pouvez définir quels types de publication activeront Elementor dans la page des réglages.</p>\n</p>\n<dt id="what%20is%20the%20difference%20between%20elementor%27s%20free%20editor%20plugin%20and%20elementor%20editor%20pro%3F">\nWhat is the difference between Elementor&rsquo;s free Editor plugin and Elementor Editor Pro?\n</h4>\n<p>\n<p>Elementor Editor’s Free version allows you to explore our revolutionary drag &amp; drop live editor, basic widgets and templates. Elementor Editor Pro (Essential, Advanced, Expert, Studio, and Agency) empowers you with more professional tools that speed up your workflow, give you access to human-powered support, help you build more advanced content, and convert visitors. See full comparison here.</p>\n</p>\n<dt id="how%20can%20i%20become%20a%20contributor%3F">\nHow can I become a Contributor?\n</h4>\n<p>\n<p>If you want to contribute, go to our <a href="https://github.com/elementor/elementor" rel="nofollow ugc">Elementor GitHub Repository</a> and see where you can help.<br />\nYou can also add a new language via <a href="https://go.elementor.com/wp-repo-description-tab-wordpress-plugin-translate/" rel="nofollow ugc">translate.wordpress.org</a>. We’ve built a short guide explaining <a href="https://go.elementor.com/wp-repo-description-tab-wordpress-plugin-translate-faq/" rel="nofollow ugc">how to translate and localize the plugin</a>.</p>\n</p>\n\n";s:9:"changelog";s:2333:"<h4>4.1.1 &#8211; 2026-05-27</h4>\n<ul>\n<li>Security Fix: Improved code security enforcement in content handling</li>\n<li>Security Fix: Improved code security enforcement in template handling</li>\n<li>Fix: Hiding one filter prevents other filters from being applied &#8211; Atomic Editor</li>\n</ul>\n<h4>4.1.0 &#8211; 2026-05-26</h4>\n<ul>\n<li>New: Introducing the Design System panel for managing Variables and Classes in one place &#8211; Atomic Editor</li>\n<li>New: Introducing Angie in the Editor to help generate and modify Atomic layouts, Components, Forms, Classes, and Variables &#8211; Atomic Editor</li>\n<li>New: Introducing Markdown rendering as an Alpha experiment to improve how content is structured for AI systems</li>\n<li>Tweak: Added import and export for Variables and Classes from the Design System panel &#8211; Atomic Editor</li>\n<li>Tweak: Increased the Class limit to 1000 &#8211; Atomic Editor</li>\n<li>Tweak: Added duplicate support for Variables in the Variables Manager &#8211; Atomic Editor</li>\n<li>Tweak: Added duplicate support for Classes in the Class field &#8211; Atomic Editor</li>\n<li>Tweak: Added support for Variables in additional style controls, including Effects, Filters, and Box Shadow &#8211; Atomic Editor</li>\n<li>Tweak: Added multi-select support to Direction control in Interactions &#8211; Atomic Editor</li>\n<li>Tweak: Added Interaction actions to the History panel &#8211; Atomic Editor</li>\n<li>Tweak: Added support for negative Box Shadow values &#8211; Atomic Editor</li>\n<li>Tweak: Improved reordering of Component properties with full drag-and-drop support &#8211; Atomic Editor</li>\n<li>Tweak: Updated Position and Z-index control visibility and behavior &#8211; Atomic Editor</li>\n<li>Tweak: Updated the minimum required WordPress version to 6.8</li>\n<li>Tweak: Added the External URL option to Image control &#8211; Atomic Editor</li>\n<li>Fix: Slide Interactions can be applied without selecting a direction &#8211; Atomic Editor</li>\n<li>Fix: Undo does not work as expected for individual Class properties &#8211; Atomic Editor</li>\n<li>Fix: Font family values persist on Global Classes after deletion &#8211; Atomic Editor</li>\n</ul>\n<p><a href="https://go.elementor.com/full-changelog/" rel="nofollow ugc">Voir le journal des modifications pour toutes les versions.</a></p>\n";s:11:"screenshots";s:3162:"<ol><li><a href="https://ps.w.org/elementor/assets/screenshot-1.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-1.gif?rev=3005087" alt="&lt;strong&gt;Visual Drag and Drop Editor&lt;/strong&gt; - Design your website layouts and place any element anywhere on the page for pixel-perfect designs."></a><p><strong>Visual Drag and Drop Editor</strong> - Design your website layouts and place any element anywhere on the page for pixel-perfect designs.</p></li><li><a href="https://ps.w.org/elementor/assets/screenshot-2.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-2.gif?rev=3005087" alt="&lt;strong&gt;Full Design System&lt;/strong&gt; - Enjoy a professional workflow and ensure consistency across your site. Define your settings, use them globally, and instantly adjust them any time."></a><p><strong>Full Design System</strong> - Enjoy a professional workflow and ensure consistency across your site. Define your settings, use them globally, and instantly adjust them any time.</p></li><li><a href="https://ps.w.org/elementor/assets/screenshot-3.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-3.gif?rev=3005087" alt="&lt;strong&gt;Responsive Design&lt;/strong&gt; Fully edit your website and customize the behavior on desktop, tablet, &amp; mobile to optimize the visitor experience on every device."></a><p><strong>Responsive Design</strong> Fully edit your website and customize the behavior on desktop, tablet, &amp; mobile to optimize the visitor experience on every device.</p></li><li><a href="https://ps.w.org/elementor/assets/screenshot-4.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-4.gif?rev=3005087" alt="&lt;strong&gt;Kits and Templates&lt;/strong&gt; - Jumpstart your web creation process or get inspired with professionally-designed templates or full website kits available for your immediate customization."></a><p><strong>Kits and Templates</strong> - Jumpstart your web creation process or get inspired with professionally-designed templates or full website kits available for your immediate customization.</p></li><li><a href="https://ps.w.org/elementor/assets/screenshot-5.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-5.gif?rev=3005087" alt="&lt;strong&gt;Nested Elements&lt;/strong&gt; Leverage Elementor Editor&#039;s Nested widgets to place any widget inside the content area of another widget - like Tabs, and Accordion for complete design flexibility."></a><p><strong>Nested Elements</strong> Leverage Elementor Editor\'s Nested widgets to place any widget inside the content area of another widget - like Tabs, and Accordion for complete design flexibility.</p></li><li><a href="https://ps.w.org/elementor/assets/screenshot-6.gif?rev=3005087"><img src="https://ps.w.org/elementor/assets/screenshot-6.gif?rev=3005087" alt="&lt;strong&gt;Motion Effects&lt;/strong&gt; - Add entrance animations and transitions to any element in your website to captivate visitors."></a><p><strong>Motion Effects</strong> - Add entrance animations and transitions to any element in your website to captivate visitors.</p></li></ol>";s:7:"reviews";s:17394:"<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Solid, Not Perfect</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="4 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="4" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/sophie85/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/dc86d252b80a8231f51feaacd827b09ccd5312a7120b2cfa2783cbd2539b4a7d?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/dc86d252b80a8231f51feaacd827b09ccd5312a7120b2cfa2783cbd2539b4a7d?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/sophie85/" class="reviewer-name">sophie85</a> le <span class="review-date">juin 4, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>drag &amp; drop is genuinely useful, got my site running faster than expected. v4 feels a bit heavy tho. free version does the job tbh</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Powerful, With a Catch</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="4 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="4" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/sidney30/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/d4d48902268170e29bbb47262fa5f69e58b2ad0c04c108282c51d6aba50a95e6?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/d4d48902268170e29bbb47262fa5f69e58b2ad0c04c108282c51d6aba50a95e6?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/sidney30/" class="reviewer-name">sidney30</a> le <span class="review-date">juin 3, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Drag and drop works like a charm, built 3 landing pages w/ zero coding. Only gripe? Loads a ton of CSS even for simple pages. Site speed took a hit tbh. Worth it for the design freedom tho, just pair it w/ a cache plugin</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Solid But Pricey</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="4 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="4" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/clifford2/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/9bd4aa7c5e1d2bc8e630762bbd57cbb857e927d560675de3fcdd27c1d073f14e?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/9bd4aa7c5e1d2bc8e630762bbd57cbb857e927d560675de3fcdd27c1d073f14e?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/clifford2/" class="reviewer-name">Clifford <small>(clifford2)</small></a> le <span class="review-date">juin 1, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>widget library is actually impressive ngl. set up my portfolio site w it, no dev needed. only thing is u gotta go pro for the real good stuff. free ver is ok bt feels limited after a while</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Absolute Rubbish</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="1 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="1" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/stephen54/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/d2131a0e847f5362da287503be9de7acbbe8816c28500b7113e7118154ed26d7?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/d2131a0e847f5362da287503be9de7acbbe8816c28500b7113e7118154ed26d7?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/stephen54/" class="reviewer-name">stephen54</a> le <span class="review-date">juin 1, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Why have you changed everything do you think people have nothing better to do than rummage around trying to find out how to use the latest update. Very frustrating.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Supporto tecnico inesistente: ticket chiusi senza soluzione</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="1 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="1" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/robertodimaio/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/c5a73b70ae454d20134960df5337cd01b8fceb12b4070f210d8e260aa30c8578?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/c5a73b70ae454d20134960df5337cd01b8fceb12b4070f210d8e260aa30c8578?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/robertodimaio/" class="reviewer-name">robertodimaio</a> le <span class="review-date">mai 29, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>La mia esperienza con Elementor è stata deludente, soprattutto per quanto riguarda il supporto tecnico gratuito.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A fronte di un problema reale e documentato, ho aperto diversi ticket fornendo informazioni dettagliate, screenshot e prove dei test effettuati. Purtroppo, invece di ricevere indicazioni utili per la risoluzione del problema, le discussioni sono state chiuse senza una risposta concreta o senza che il problema venisse effettivamente risolto.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dopo numerose verifiche ho accertato che il malfunzionamento era legato a Elementor, ma nonostante ciò non ho ricevuto un adeguato supporto tecnico. Ritengo che un\'assistenza efficace sia un elemento fondamentale per un prodotto così diffuso e utilizzato in ambito professionale.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Il plugin offre molte funzionalità interessanti, ma la qualità dell\'assistenza rappresenta un aspetto che dovrebbe essere migliorato significativamente.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Elementor Is Great for Small to Medium Sites, but Gutenberg Offers Better Perfor</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="4 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="4" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/tanyazadonsky/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/9e887d8f9f3c3025420aaffd07f0ad8245b439ce688e3fc7edcf11d56582ffb9?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/9e887d8f9f3c3025420aaffd07f0ad8245b439ce688e3fc7edcf11d56582ffb9?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/tanyazadonsky/" class="reviewer-name">tanyazadonsky</a> le <span class="review-date">mai 29, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Gutenberg has really improved as a page-building experience. Its block-based editor feels lighter, more integrated into WordPress core, and is generally faster for content-heavy sites. For developers and those who prefer minimal plugins, Gutenberg is an excellent choice—its performance and native compatibility make it stand out, especially for larger projects or more complex layouts.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>That said, Elementor shines for small to medium sites where speed of design and flexibility matter most. Its drag-and-drop interface, pre-built templates, and extensive styling options make it extremely user-friendly, even for those without coding experience. For quick prototypes or sites that need more visual flair, Elementor still has the edge.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>In short, Gutenberg is increasingly robust and ideal for streamlined, scalable projects, while Elementor remains a strong option for smaller, design-focused sites where ease-of-use and rapid development are priorities.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">We use Elementor every day</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="5 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="5" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/marinelray/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/8f90b4c5d52510744c2e6ffe312d8de35a05123dd282d3187720221cb20860ae?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/8f90b4c5d52510744c2e6ffe312d8de35a05123dd282d3187720221cb20860ae?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/marinelray/" class="reviewer-name">marinelray</a> le <span class="review-date">mai 28, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Elementor is an amazing WordPress builder.  It gets updates regularly, is easy to use to build great-looking pages. </p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Elementor 4. Not for me :(</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="5 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="5" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/nortonc/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/53c76b4686cb7108db45fe46a62cf5c54330f71c699493f640239d42068897f9?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/53c76b4686cb7108db45fe46a62cf5c54330f71c699493f640239d42068897f9?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/nortonc/" class="reviewer-name">nortonc</a> le <span class="review-date">mai 25, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Using Elementor for years - this latest version 4 is not for me. The loading screen takes forever, if it even loads, its cluttered with the new ATOM items. The learning curve and all the settings are overwhelming. I think you missed the mark on this one.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">No Dev? No Problem</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="4 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="4" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-empty"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/noelbrito/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/01bb421dcc01edb33e3a9fd5ad72f00ef328b5a1970b31dad7444ecc4268de80?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/01bb421dcc01edb33e3a9fd5ad72f00ef328b5a1970b31dad7444ecc4268de80?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/noelbrito/" class="reviewer-name">noelbrito</a> le <span class="review-date">mai 25, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Built my whole biz site on my own, zero coding needed. Took me a wknd bt the result looks rly pro. Only annoying part is some gud widgets r locked behind pro. Still worth it tho</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class="review">\n	<div class="review-head">\n		<div class="reviewer-info">\n			<div class="review-title-section">\n				<h4 class="review-title">Sembra semplice anche per non programmatori</h4>\n				<div class="star-rating">\n				<div class="wporg-ratings" aria-label="5 sur 5 étoiles" data-title-template="%s sur 5 étoiles" data-rating="5" style="color:#ffb900;"><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span><span class="star dashicons dashicons-star-filled"></span></div>				</div>\n			</div>\n			<p class="reviewer">\n				Par <a href="https://profiles.wordpress.org/faunomuschio/"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/bca914d1b635101d41032209030d64464879706211881e88fbd6967f63ed637c?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/bca914d1b635101d41032209030d64464879706211881e88fbd6967f63ed637c?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href="https://profiles.wordpress.org/faunomuschio/" class="reviewer-name">faunomuschio</a> le <span class="review-date">mai 23, 2026</span>			</p>\n		</div>\n	</div>\n	<div class="review-body"><!-- wp:paragraph -->\n<p>Sto costruendo un giornale online per un\'associazione e mi sta aiutando davvero molto!</p>\n<!-- /wp:paragraph --></div>\n</div>\n";}s:17:"short_description";s:159:"The Elementor Website Builder has it all: drag and drop page builder, Atomic Editor, pixel perfect design, global and reusable style systems, mobile r &hellip;";s:13:"download_link";s:58:"https://downloads.wordpress.org/plugin/elementor.4.1.1.zip";s:14:"upgrade_notice";a:0:{}s:11:"screenshots";a:6:{i:1;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-1.gif?rev=3005087";s:7:"caption";s:144:"<strong>Visual Drag and Drop Editor</strong> - Design your website layouts and place any element anywhere on the page for pixel-perfect designs.";}i:2;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-2.gif?rev=3005087";s:7:"caption";s:185:"<strong>Full Design System</strong> - Enjoy a professional workflow and ensure consistency across your site. Define your settings, use them globally, and instantly adjust them any time.";}i:3;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-3.gif?rev=3005087";s:7:"caption";s:170:"<strong>Responsive Design</strong> Fully edit your website and customize the behavior on desktop, tablet, &amp; mobile to optimize the visitor experience on every device.";}i:4;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-4.gif?rev=3005087";s:7:"caption";s:193:"<strong>Kits and Templates</strong> - Jumpstart your web creation process or get inspired with professionally-designed templates or full website kits available for your immediate customization.";}i:5;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-5.gif?rev=3005087";s:7:"caption";s:197:"<strong>Nested Elements</strong> Leverage Elementor Editor\'s Nested widgets to place any widget inside the content area of another widget - like Tabs, and Accordion for complete design flexibility.";}i:6;a:2:{s:3:"src";s:62:"https://ps.w.org/elementor/assets/screenshot-6.gif?rev=3005087";s:7:"caption";s:127:"<strong>Motion Effects</strong> - Add entrance animations and transitions to any element in your website to captivate visitors.";}}s:4:"tags";a:5:{s:13:"drag-and-drop";s:13:"drag-and-drop";s:6:"editor";s:6:"editor";s:9:"elementor";s:9:"elementor";s:12:"landing-page";s:12:"landing page";s:12:"page-builder";s:12:"page builder";}s:8:"versions";a:437:{s:5:"3.0.0";s:58:"https://downloads.wordpress.org/plugin/elementor.3.0.0.zip";s:5:"3.0.1";s:58:"https://downloads.wordpress.org/plugin/elementor.3.0.1.zip";s:6:"3.0.10";s:59:"https://downloads.wordpress.org/plugin/elementor.3.0.10.zip";s:6:"3.0.11";s:59:"https://downloads.wordpress.org/plugin/elementor.3.0.11.zip";s:6:"3.0.12";s:59:"https://downloads.wordpress.org/plugin/elementor.3.0.12.zip"