	(558, 108, '_elementor_page_settings', 'a:12:{s:9:"site_name";s:32:"DOMAINE La Vignerie À VINCELLES";s:13:"system_colors";a:4:{i:0;a:3:{s:3:"_id";s:7:"primary";s:5:"title";s:9:"Principal";s:5:"color";s:7:"#6EC1E4";}i:1;a:3:{s:3:"_id";s:9:"secondary";s:5:"title";s:10:"Secondaire";s:5:"color";s:7:"#54595F";}i:2;a:3:{s:3:"_id";s:4:"text";s:5:"title";s:5:"Texte";s:5:"color";s:7:"#7A7A7A";}i:3;a:3:{s:3:"_id";s:6:"accent";s:5:"title";s:9:"Accentué";s:5:"color";s:7:"#61CE70";}}s:13:"custom_colors";a:0:{}s:17:"system_typography";a:4:{i:0;a:5:{s:3:"_id";s:7:"primary";s:5:"title";s:9:"Principal";s:21:"typography_typography";s:6:"custom";s:22:"typography_font_family";s:6:"Roboto";s:22:"typography_font_weight";s:3:"600";}i:1;a:5:{s:3:"_id";s:9:"secondary";s:5:"title";s:10:"Secondaire";s:21:"typography_typography";s:6:"custom";s:22:"typography_font_family";s:11:"Roboto Slab";s:22:"typography_font_weight";s:3:"400";}i:2;a:5:{s:3:"_id";s:4:"text";s:5:"title";s:5:"Texte";s:21:"typography_typography";s:6:"custom";s:22:"typography_font_family";s:6:"Roboto";s:22:"typography_font_weight";s:3:"400";}i:3;a:5:{s:3:"_id";s:6:"accent";s:5:"title";s:9:"Accentué";s:21:"typography_typography";s:6:"custom";s:22:"typography_font_family";s:6:"Roboto";s:22:"typography_font_weight";s:3:"500";}}s:17:"custom_typography";a:0:{}s:21:"default_generic_fonts";s:10:"Sans-serif";s:26:"body_background_background";s:7:"classic";s:19:"page_title_selector";s:0:"";s:27:"hello_footer_copyright_text";s:22:"Tous droits réservés";s:11:"viewport_md";i:768;s:11:"viewport_lg";i:1025;s:21:"body_background_image";a:5:{s:3:"url";s:72:"http://localhost:8098/wp-content/uploads/2026/05/Arriere-plan-scaled.png";s:2:"id";i:101;s:4:"size";s:0:"";s:3:"alt";s:0:"";s:6:"source";s:7:"library";}}'),
